              int(cosize(sA_layout) * sizeof(TypeA)));
  std::printf("per-CTA smem B bytes/stage: %d  (full-N would be %d)\n",
              int(cosize(sB_layout) * sizeof(TypeB)),
              int(2 * cosize(sB_layout) * sizeof(TypeB)));

